head.script:
var i = 0;
scwin.fn_addTab = function() {
	var tabOpt = {
		label : "임시화면" + i,
		closable : true
	};
	var contOpt = {
		frameMode : "wframe",
		src : "/sample/common_link/windowContainer_processMsgFrame_WindowContainer_WESE-1002_(WSQ-5874)_sub2.xml"
	};
	tabControl1.addTab('tab0' + i, tabOpt, contOpt);
	var idx = tabControl1.getTabCount();
	tabControl1.setSelectedTabIndex(idx - 1);
	i++;
};

scwin.trigger2_onclick = function(e) {
	var ii = tabControl1.getFrame(tabControl1.getSelectedTabIndex()).id;
	WebSquare.layer.showProcessMessage("Tab_test..", {scope:ii});
	$p.setTimeout(function() {
		scwin.fn_addTab();
		WebSquare.layer.hideProcessMessage({scope:ii});
	}, {delay:3000, key:""});
};
